mapper.select:
SELECT r.*, p.pet_name, u.real_name FROM pet_reserve r LEFT JOIN pet p ON r.pet_id = p.pet_id LEFT JOIN user u ON r.user_id = u.user_id WHERE 1=1
AND r.reserve_status = #{reserveStatus}
AND r.user_id = #{userId}
AND r.pet_id = #{petId}
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
ORDER BY r.create_time DESC
